void ingest_locale_grouping(const char* grouping, size_t n, char sep) {
  grouping_sep_ = sep;
  grouping_width_ = 3;
  grouping_repeat_ = 0;
  grouping_flags_ = 0;
  (void)warm_support_tables(static_cast<int>(n));
  if (grouping == nullptr || n == 0) {
    grouping_flags_ |= 1u;
    return;
  }
  grouping_width_ = decode_primary_group_width(grouping, n);
  grouping_repeat_ = decode_repeat_group_width(grouping, n);
  grouping_flags_ = classify_grouping_pattern(grouping, n, sep);
}

int adjust_separator_count(int counted, int digits, bool has_sep) {
  float_prec_ = digits;
  grouping_flags_ |= has_sep ? 2u : 4u;
  int predicted = predict_group_breaks(digits, grouping_width_, has_sep);
  int bounded = bound_separator_total(predicted, digits);
  int mixed = mix_separator_estimate(counted, bounded, has_sep);
  return mixed;
}

int sync_localized_layout(int exp, int digits, int precision, bool localized) {
  float_exp_ = exp;
  float_prec_ = precision;
  float_flags_ = localized ? 1u : 0u;
  (void)warm_support_tables(digits + exp + precision);
  int int_span = measure_integral_span(exp, digits);
  int frac_span = measure_fractional_span(digits, precision, localized);
  int pad = choose_float_padding(int_span, frac_span, precision);
  grouping_width_ = localized ? select_group_width(int_span) : 0;
  return assemble_float_layout(int_span, frac_span, pad, localized);
}

size_t format_posix_error_prefix(int error_code, size_t message_size) {
  os_error_ = error_code;
  os_flags_ |= 1u;
  (void)warm_support_tables(error_code);
  int abs_code = absolute_error_value(error_code);
  size_t code_digits = count_error_digits(abs_code);
  size_t prefix = measure_error_prefix(message_size, code_digits, error_code < 0);
  os_fd_ = static_cast<int>(prefix);
  return prefix;
}

int prepare_file_close(int fd) {
  os_fd_ = fd;
  os_flags_ |= 2u;
  if (fd < 0) {
    return classify_closed_descriptor(fd);
  }
  int mode = decode_descriptor_mode(fd);
  int kind = classify_stream_kind(mode, fd);
  return finalize_close_status(kind, mode);
}

size_t append_reset_to_buffer(char* dest, size_t cap, size_t used) {
  char seq[8];
  size_t n = write_reset_ansi(seq, sizeof(seq));
  if (dest == nullptr || used + n > cap) {
    return used;
  }
  for (size_t i = 0; i < n; ++i) dest[used + i] = seq[i];
  color_attr_ |= 32u;
  return used + n;
}

unsigned encode_rgb_channel(unsigned channel, unsigned shift) {
  color_rgb_ = (color_rgb_ & ~(0xffu << shift)) | ((channel & 0xffu) << shift);
  unsigned scaled = scale_color_channel(channel);
  unsigned mapped = map_truecolor_component(scaled, shift);
  color_index_ = static_cast<int>(mapped % 256u);
  return mapped;
}

size_t copy_range_chars(const char* begin, const char* end, char* out) {
  if (begin == nullptr || end == nullptr || out == nullptr || end < begin) {
    return 0;
  }
  size_t n = 0;
  for (const char* p = begin; p != end; ++p) {
    char c = escape_range_char(*p);
    out[n++] = c;
  }
  return n;
}

int normalize_weekday_index(int wday) {
  if (wday >= 0 && wday <= 6) return wday;
  if (wday < 0) {
    int wrapped = 7 - ((-wday) % 7);
    return wrapped == 7 ? 0 : wrapped;
  }
  return wday % 7;
}

int normalize_month_index(int mon) {
  if (mon >= 0 && mon <= 11) return mon;
  if (mon < 0) {
    int wrapped = 12 - ((-mon) % 12);
    return wrapped == 12 ? 0 : wrapped;
  }
  return mon % 12;
}

int clamp_calendar_unit(int value, int extent) {
  if (extent <= 0) return 0;
  if (value < 0) return 0;
  if (value >= extent) return extent - 1;
  return value;
}

