unsigned pack_hms_fields(unsigned a, unsigned b, unsigned c) {
  unsigned aa = a > 99 ? 99 : a;
  unsigned bb = b > 99 ? 99 : b;
  unsigned cc = c > 99 ? 99 : c;
  return aa | (bb << 8) | (cc << 16);
}

unsigned to_bcd_triplets(unsigned packed) {
  unsigned out = 0;
  for (int shift = 0; shift <= 16; shift += 8) {
    unsigned field = (packed >> shift) & 0xffu;
    unsigned hi = field / 10u;
    unsigned lo = field % 10u;
    out |= ((hi << 4) | lo) << shift;
  }
  return out;
}

