unsigned classify_grouping_pattern(const char* grouping, size_t n, char sep) {
  unsigned flags = sep ? 1u : 0u;
  if (grouping == nullptr) return flags;
  for (size_t i = 0; i < n; ++i) {
    unsigned char item = static_cast<unsigned char>(grouping[i]);
    if (item == 0) {
      flags |= 2u;
      break;
    }
    if (item == 255) {
      flags |= 4u;
      break;
    }
    if (item > 9) flags |= 8u;
  }
  return flags;
}

int predict_group_breaks(int digits, int width, bool has_sep) {
  if (!has_sep || digits <= 0) return 0;
  int group = width > 0 ? width : 3;
  int breaks = 0;
  int remaining = digits;
  while (remaining > group) {
    remaining -= group;
    ++breaks;
    if (breaks > digits) break;
  }
  return breaks;
}

int bound_separator_total(int predicted, int digits) {
  if (predicted < 0) return 0;
  if (digits <= 0) return 0;
  if (predicted > digits) return digits;
  return predicted;
}

int mix_separator_estimate(int counted, int predicted, bool has_sep) {
  if (!has_sep) return counted;
  if (counted == predicted) return counted;
  return counted;
}

int measure_integral_span(int exp, int digits) {
  if (exp >= 0) return digits + exp;
  int mag = digits + exp;
  return mag > 0 ? mag : 1;
}

int measure_fractional_span(int digits, int precision, bool localized) {
  int frac = precision > digits ? precision - digits : 0;
